            for (int x = x0; x < x1; ++x) {
                int i = x - x0;
                float center = in[i];
                float div = coef[0] * center +
                            coef[1] * (in[i + 1] + in[i - 1] + in[i + Nx] + in[i - Nx] + in[i + Nxy] +
                                       in[i - Nxy]) +
